import { useState } from 'react';
import { changePassword } from '../services/api';

function initials(name = '') { return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(); }

export default function ProfileScreen({ user, onSave, onUploadImages }) {
  const [form, setForm] = useState({ name: user.name || '', batch_year: user.batch_year || '', current_company: user.current_company || '', job_title: user.job_title || '', location: user.location || '', bio: user.bio || '', phone_country_code: user.phone_country_code || '+91', phone_number: user.phone_number || '', address: user.address || '', country: user.country || '', pincode: user.pincode || '' });
  const [images, setImages] = useState({ avatar_image: user.avatar_image || '', cover_image: user.cover_image || '' });
  const [saved, setSaved] = useState(false);
  const [uploading, setUploading] = useState('');
  const [passwords, setPasswords] = useState({ current_password: '', new_password: '' });
  const [passwordMessage, setPasswordMessage] = useState('');
  async function submit(event) { event.preventDefault(); await onSave({ ...form, batch_year: form.batch_year ? Number(form.batch_year) : undefined }); setSaved(true); }
  async function upload(field, file) { if (!file) return; setUploading(field); try { const result = await onUploadImages({ [field]: file }); setImages((current) => ({ ...current, ...result })); } finally { setUploading(''); } }
  async function submitPassword(event) { event.preventDefault(); setPasswordMessage(''); try { await changePassword(passwords); setPasswords({ current_password: '', new_password: '' }); setPasswordMessage('Password changed'); } catch (error) { setPasswordMessage(error.message); } }
  return <div className="profile-screen"><div className="profile-cover" style={images.cover_image ? { backgroundImage: `url(${images.cover_image})` } : undefined}><label className="cover-upload">{uploading === 'cover_image' ? 'Uploading...' : 'Upload cover'}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => upload('cover_image', event.target.files?.[0])} /></label></div><div className="screen-heading"><div><span className="section-kicker">YOUR STORY</span><h2>My profile</h2><p>Keep your details current so classmates can find you.</p></div><label className="avatar avatar-profile avatar-upload">{images.avatar_image ? <img src={images.avatar_image} alt="Profile" /> : initials(form.name)}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => upload('avatar_image', event.target.files?.[0])} />{uploading === 'avatar_image' && <small>...</small>}</label></div><form className="profile-form" onSubmit={submit}><label>Full name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Batch year<input type="number" value={form.batch_year} onChange={(event) => setForm({ ...form, batch_year: event.target.value })} /></label><label>Phone country code<select value={form.phone_country_code} onChange={(event) => setForm({ ...form, phone_country_code: event.target.value })}><option value="+91">+91 India</option><option value="+1">+1 United States/Canada</option><option value="+44">+44 United Kingdom</option><option value="+61">+61 Australia</option><option value="+65">+65 Singapore</option><option value="+971">+971 UAE</option></select></label><label>Phone number<input inputMode="numeric" pattern="[0-9]{6,15}" value={form.phone_number} onChange={(event) => setForm({ ...form, phone_number: event.target.value.replace(/\D/g, '') })} placeholder="9876543210" /></label><label>Current company<input value={form.current_company} onChange={(event) => setForm({ ...form, current_company: event.target.value })} /></label><label>Job title<input value={form.job_title} onChange={(event) => setForm({ ...form, job_title: event.target.value })} /></label><label>Location<input value={form.location} onChange={(event) => setForm({ ...form, location: event.target.value })} /></label><label>Country<input value={form.country} onChange={(event) => setForm({ ...form, country: event.target.value })} /></label><label className="wide-field">Address<input value={form.address} onChange={(event) => setForm({ ...form, address: event.target.value })} /></label><label>Pincode<input inputMode="numeric" pattern="[0-9]{4,10}" value={form.pincode} onChange={(event) => setForm({ ...form, pincode: event.target.value.replace(/\D/g, '') })} /></label><label className="wide-field">Bio<textarea value={form.bio} onChange={(event) => setForm({ ...form, bio: event.target.value })} rows="4" /></label><div className="form-footer"><button className="primary-button">Save profile</button>{saved && <span className="saved-note">Profile updated</span>}</div></form><form className="profile-form password-form" onSubmit={submitPassword}><h3 className="wide-field">Change password</h3><label>Current password<input type="password" required value={passwords.current_password} onChange={(event) => setPasswords({ ...passwords, current_password: event.target.value })} /></label><label>New password<input type="password" minLength="8" required value={passwords.new_password} onChange={(event) => setPasswords({ ...passwords, new_password: event.target.value })} /></label><div className="form-footer"><button className="primary-button">Update password</button>{passwordMessage && <span className="saved-note">{passwordMessage}</span>}</div></form></div>;
}
